// ---------------------------------------------------------------------------
// Golden plumbing (prompts_corpus.golden.json — one document, UseNumber so
// int-vs-float slot values survive the round trip as json.Number).
// ---------------------------------------------------------------------------

func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_prompts.py): %v", name, err)
	}
	return raw
}

// loadCorpus decodes the golden with UseNumber: Python values like 5 and
// 5.0 must stay distinguishable (str(5) == "5", str(5.0) == "5.0").
func loadCorpus(t *testing.T) map[string]any {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(goldenBytes(t, "prompts_corpus.golden.json")))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		t.Fatalf("decode corpus: %v", err)
	}
	return doc
}

func corpusSection(t *testing.T, doc map[string]any, key string) []any {
	t.Helper()
	v, ok := doc[key].([]any)
	if !ok {
		t.Fatalf("corpus section %q missing or wrong shape", key)
	}
	return v
}

// corpusSlots converts the golden's [[name, value], ...] pairs (value kept
// as json.Number / string / bool / nil) into Slot values in call order.
func corpusSlots(t *testing.T, v any) []Slot {
	t.Helper()
	pairs, ok := v.([]any)
	if !ok {
		t.Fatalf("corpus pairs wrong shape: %T", v)
	}
	slots := make([]Slot, 0, len(pairs))
	for _, p := range pairs {
		pair, ok := p.([]any)
		if !ok || len(pair) != 2 {
			t.Fatalf("corpus pair wrong shape: %#v", p)
		}
		name, ok := pair[0].(string)
		if !ok {
			t.Fatalf("corpus slot name not a string: %#v", pair[0])
		}
		var value any
		switch vv := pair[1].(type) {
		case string, bool, nil, json.Number:
			value = vv
		default:
			t.Fatalf("corpus slot value has unexpected type: %T", pair[1])
		}
		slots = append(slots, Slot{Name: name, Value: value})
	}
	return slots
}

// corpusTemplate extracts a template-or-null entry field.
func corpusTemplate(t *testing.T, v any) any {
	t.Helper()
	if v == nil {
		return nil
	}
	s, ok := v.(string)
	if !ok {
		t.Fatalf("corpus template not a string: %#v", v)
	}
	return s
}

func corpusString(t *testing.T, v any) string {
	t.Helper()
	s, ok := v.(string)
	if !ok {
		t.Fatalf("corpus string field wrong type: %T", v)
	}
	return s
}

// asPromptError asserts err is a *PromptError and returns it.
func asPromptError(t *testing.T, err error) *PromptError {
	t.Helper()
	if err == nil {
		t.Fatalf("expected *PromptError, got nil")
	}
	var pe *PromptError
	if !errors.As(err, &pe) {
		t.Fatalf("expected *PromptError, got %T: %v", err, err)
	}
	return pe
}

