// Port of test_refuses_unfilled_slot.
func TestRefusesUnfilledSlot(t *testing.T) {
	_, err := FillTemplate("Hello {{NAME}} and {{OTHER}}", Slot{Name: "NAME", Value: "x"})
	pe := asPromptError(t, err)
	if pe.Msg != "prompt slot(s) left unfilled: OTHER" {
		t.Fatalf("message = %q", pe.Msg)
	}
}

