// TestGoldenSlotsIn pins the {{SLOT}} grammar: order, dedupe (first
// position wins), and every boundary (lowercase, leading digit, dash,
// space, empty, non-ASCII — none are slots).
func TestGoldenSlotsIn(t *testing.T) {
	doc := loadCorpus(t)
	for _, entry := range corpusSection(t, doc, "slots_in") {
		e, ok := entry.([]any)
		if !ok || len(e) != 2 {
			t.Fatalf("slots_in entry wrong shape: %#v", entry)
		}
		tmpl := corpusTemplate(t, e[0])
		var want []string
		for _, n := range e[1].([]any) {
			want = append(want, corpusString(t, n))
		}
		var got []string
		switch tv := tmpl.(type) {
		case nil:
			got = SlotsIn("") // Python slots_in(None) → template or ''
		case string:
			got = SlotsIn(tv)
		}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("SlotsIn(%#v) = %v, want %v", tmpl, got, want)
		}
	}
}

// TestGoldenFillTemplateOK pins successful fills: repeated slots, unused
// extra values, non-string values through Python str() semantics (5 vs
// 5.0, True/False, 1e15 positional vs 1e-05 scientific), the guard's
// partial-marker pass-through ({{partial, {{9X}}), and the BOM quirk (a
// BOM is NOT stripped — it would corrupt slot 1 in Python too).
func TestGoldenFillTemplateOK(t *testing.T) {
	doc := loadCorpus(t)
	for _, entry := range corpusSection(t, doc, "fill_ok") {
		e, ok := entry.([]any)
		if !ok || len(e) != 3 {
			t.Fatalf("fill_ok entry wrong shape: %#v", entry)
		}
		tmpl := corpusTemplate(t, e[0])
		slots := corpusSlots(t, e[1])
		want := corpusString(t, e[2])
		got, err := FillTemplate(tmpl, slots...)
		if err != nil {
			t.Fatalf("FillTemplate(%#v, %v): %v", tmpl, slots, err)
		}
		if got != want {
			t.Fatalf("FillTemplate(%#v, %v)\n got %q\nwant %q", tmpl, slots, got, want)
		}
	}
}

// TestGoldenFillErrors pins every refusal message byte-exact, including
// the two-stage None law: a None value FOR a declared slot is reported by
// the unfilled-slot check first; "got None" only fires for non-slot keys.
func TestGoldenFillErrors(t *testing.T) {
	doc := loadCorpus(t)
	for _, entry := range corpusSection(t, doc, "fill_errors") {
		e, ok := entry.([]any)
		if !ok || len(e) != 3 {
			t.Fatalf("fill_errors entry wrong shape: %#v", entry)
		}
		tmpl := corpusTemplate(t, e[0])
		slots := corpusSlots(t, e[1])
		want := corpusString(t, e[2])
		_, err := FillTemplate(tmpl, slots...)
		if err == nil {
			t.Fatalf("FillTemplate(%#v, %v): expected error %q, got nil", tmpl, slots, want)
		}
		if err.Error() != want {
			t.Fatalf("FillTemplate(%#v, %v)\n got error %q\nwant        %q", tmpl, slots, err.Error(), want)
		}
		asPromptError(t, err)
	}
}

